import type { ApiLike } from "./api.ts";
import type { AuthUser, GreenPremiumAppearance } from "./types.ts";

const MAX_ACCOUNTS = 10;
const REFRESH_AFTER_MS = 15_000;
const POLL_EVERY_MS = 30_000;

type LinkStart = { account_link_token: string };
type Roster = { accounts: unknown[] };
type StillCurrent = () => boolean;

function account(raw: unknown): AuthUser | null {
  if (!raw || typeof raw !== "object" || Array.isArray(raw)) return null;
  const value = raw as Record<string, unknown>;
  if (!Number.isSafeInteger(value.id) || Number(value.id) <= 0) return null;
  if (typeof value.username !== "string" || typeof value.name !== "string") return null;
  const avatar = value.avatar_file_id;
  if (avatar !== undefined && avatar !== null && (!Number.isSafeInteger(avatar) || Number(avatar) <= 0)) return null;
  return {
    id: Number(value.id),
    username: value.username,
    name: value.name,
    ...(avatar === undefined ? {} : { avatar_file_id: avatar === null ? null : Number(avatar) }),
    ...(value.premium && typeof value.premium === "object"
      ? { premium: value.premium as GreenPremiumAppearance }
      : {}),
  };
}

/** Lazy-loaded server roster: account credentials remain in each device's own secure session store. */
export class CloudAccountSync {
  private readonly api: ApiLike;
  private readonly changed: () => void;
  private values: AuthUser[] = [];
  private ownerId: number | null = null;
  private fetchedAt = 0;
  private syncing = false;
  private timer: ReturnType<typeof setInterval> | null = null;

  constructor(api: ApiLike, changed: () => void) {
    this.api = api;
    this.changed = changed;
  }

  list(ownerId: number): readonly AuthUser[] {
    return this.ownerId === ownerId ? this.values : [];
  }

  find(ownerId: number, userId: number): AuthUser | undefined {
    return this.ownerId === ownerId ? this.values.find((value) => value.id === userId) : undefined;
  }

  full(ownerId: number): boolean {
    return this.ownerId === ownerId && this.values.length >= MAX_ACCOUNTS;
  }

  async startLink(): Promise<string> {
    const result = await this.api.post<LinkStart>("/v1/auth/accounts/link/start");
    const token = result?.account_link_token;
    if (typeof token !== "string" || token.length < 20) throw new Error("Invalid account-link response");
    return token;
  }

  reset(): void {
    this.stop();
    this.values = [];
    this.ownerId = null;
    this.fetchedAt = 0;
  }

  async refresh(ownerId: number, current: StillCurrent, notify = false): Promise<void> {
    if (this.syncing || !current()) return;
    this.syncing = true;
    try {
      const result = await this.api.get<Roster>("/v1/auth/accounts");
      if (!current() || !Array.isArray(result?.accounts)) return;
      const unique = new Map<number, AuthUser>();
      for (const raw of result.accounts) {
        const value = account(raw);
        if (value) unique.set(value.id, value);
      }
      if (!unique.has(ownerId) || unique.size > MAX_ACCOUNTS) return;
      const next = [...unique.values()];
      const changed = this.ownerId !== ownerId || JSON.stringify(this.values) !== JSON.stringify(next);
      this.values = next;
      this.ownerId = ownerId;
      this.fetchedAt = Date.now();
      if (notify && changed && current()) this.changed();
    } catch {
      // Offline or an older server keeps the device-local account catalogue usable.
    } finally {
      this.syncing = false;
    }
  }

  schedule(ownerId: number, current: StillCurrent): void {
    if (this.syncing || (this.ownerId === ownerId && Date.now() - this.fetchedAt < REFRESH_AFTER_MS)) return;
    void this.refresh(ownerId, current, true);
  }

  arm(ownerId: number, current: StillCurrent): void {
    this.stop();
    const timer = setInterval(() => {
      if (!current()) return this.stop();
      void this.refresh(ownerId, current, true);
    }, POLL_EVERY_MS);
    (timer as ReturnType<typeof setInterval> & { unref?: () => void }).unref?.();
    this.timer = timer;
  }

  private stop(): void {
    if (this.timer === null) return;
    clearInterval(this.timer);
    this.timer = null;
  }
}
